// One handler for the whole list reads which action was clicked.
const actions = { save: () => "saved", remove: () => "removed" };

function onListClick(event) {
  const action = actions[event.target.dataset.action];
  return action ? action() : "ignored";
}

console.log(onListClick({ target: { dataset: { action: "remove" } } }));
console.log(onListClick({ target: { dataset: {} } }));

// A tiny model of DOM nodes with parent links, like el.closest().
const list = { tag: "ul", parent: null };
const item = { tag: "li", id: 2, parent: list };
const icon = { tag: "span", parent: item };

function closest(node, tag) {
  while (node && node.tag !== tag) node = node.parent;
  return node;
}

console.log(icon.tag, closest(icon, "li").id, closest(list, "li"));

// A model of bubbling: the event visits the clicked node, then its parents.
function dispatch(path, type) {
  const log = [];
  for (const node of path) {
    const handler = node.on && node.on[type];
    if (handler && handler(log) === "stop") break;
  }
  return log.join(" > ");
}

const button = { on: { click: (log) => log.push("button") } };
const card = { on: { click: (log) => { log.push("card"); return "stop"; } } };
const page = { on: { click: (log) => log.push("page") } };

console.log(dispatch([button, card, page], "click"));
console.log(dispatch([card, page], "click"));

