// A model of async scripts: each one runs as soon as its download finishes.
const log = [];
function loadAsync(name, ms) {
  setTimeout(() => log.push(name), ms);
}

loadAsync("analytics", 30);
loadAsync("chat", 10);
setTimeout(() => console.log(log.join(" ")), 50);

// A model of defer: scripts download at the same time but run in document order.
const scripts = [
  { name: "vendor", ms: 30 },
  { name: "app", ms: 10 },
];

async function runDeferred(list) {
  const downloads = list.map((s) => new Promise((r) => setTimeout(() => r(s.name), s.ms)));
  const order = [];
  for (const d of downloads) order.push(await d);
  return order;
}

runDeferred(scripts).then((order) => console.log(order.join(" ")));

