// A simple model of how a server picks its CORS headers.
const allowed = ["https://app.com", "https://admin.app.com"];

function corsHeaders(origin) {
  if (!allowed.includes(origin)) return {};
  return { "Access-Control-Allow-Origin": origin, "Access-Control-Allow-Credentials": "true", Vary: "Origin" };
}

const ok = corsHeaders("https://app.com");
const blocked = corsHeaders("https://evil.com");
console.log(ok["Access-Control-Allow-Origin"], Object.keys(blocked).length, new URL("https://app.com:443").origin === "https://app.com");
